import{_ as r,C as n,o as i,c as d,j as t,a,b as l,w as o,E as c,a0 as h,a1 as u}from"./chunks/framework.DYnGRJP5.js";const D=JSON.parse('{"title":"Database Schema (Firestore)","description":"","frontmatter":{},"headers":[],"relativePath":"doit/database.md","filePath":"doit/database.md"}'),m={name:"doit/database.md"};function p(y,e,b,g,A,f){const s=n("Mermaid");return i(),d("div",null,[e[1]||(e[1]=t("h1",{id:"database-schema-firestore",tabindex:"-1"},[a("Database Schema (Firestore) "),t("a",{class:"header-anchor",href:"#database-schema-firestore","aria-label":'Permalink to "Database Schema (Firestore)"'},"​")],-1)),e[2]||(e[2]=t("p",null,[t("strong",null,"do.it"),a(" uses a NoSQL document structure in Cloud Firestore. To maximize speed and minimize query complexity, the data model is extremely flat. All habits are stored in a single top-level "),t("code",null,"habits"),a(" collection.")],-1)),e[3]||(e[3]=t("h2",{id:"entity-relationship-diagram",tabindex:"-1"},[a("Entity Relationship Diagram "),t("a",{class:"header-anchor",href:"#entity-relationship-diagram","aria-label":'Permalink to "Entity Relationship Diagram"'},"​")],-1)),(i(),l(h,null,{default:o(()=>[c(s,{id:"mermaid-9",class:"mermaid",graph:"erDiagram%0A%20%20%20%20USERS%20%7C%7C--o%7B%20HABITS%20%3A%20%22owns%22%0A%0A%20%20%20%20USERS%20%7B%0A%20%20%20%20%20%20%20%20string%20uid%20PK%20%22Firebase%20Auth%20ID%20(Anonymous%20or%20Permanent)%22%0A%20%20%20%20%20%20%20%20string%20displayName%20%0A%20%20%20%20%7D%0A%0A%20%20%20%20HABITS%20%7B%0A%20%20%20%20%20%20%20%20string%20id%20PK%20%22Auto-generated%20Document%20ID%22%0A%20%20%20%20%20%20%20%20string%20userId%20FK%20%22Owner's%20Auth%20UID%22%0A%20%20%20%20%20%20%20%20string%20title%20%22Habit%20name%22%0A%20%20%20%20%20%20%20%20string%20icon%20%22Emoji%20identifier%22%0A%20%20%20%20%20%20%20%20string%20color%20%22Tailwind%20color%20class%20(e.g.%20bg-blue-500)%22%0A%20%20%20%20%20%20%20%20string%20frequency%20%22daily%2C%20weekly%2C%20etc.%22%0A%20%20%20%20%20%20%20%20string%5B%5D%20completedDates%20%22Array%20of%20ISO%20Strings%20(YYYY-MM-DD)%22%0A%20%20%20%20%20%20%20%20timestamp%20createdAt%20%22Initialization%20Date%22%0A%20%20%20%20%7D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=u('<h2 id="security-rules-limitations" tabindex="-1">Security Rules &amp; Limitations <a class="header-anchor" href="#security-rules-limitations" aria-label="Permalink to &quot;Security Rules &amp; Limitations&quot;">​</a></h2><p>The structure is heavily secured by Firebase Security Rules ensuring users can only read/write documents where the <code>userId</code> field matches their authenticated UID.</p><p><strong>Wait, where are the &quot;users&quot; stored?</strong> The beauty of the <code>do.it</code> database schema is that it largely ignores a <code>users</code> collection. Because the app heavily leans on Firebase Anonymous Auth, storing a separate user document for every single person who casually visits the landing page would bloat the database rapidly.</p><p>Instead, the identity layer is handled entirely by Firebase Auth. The <code>HABITS</code> collection binds directly to the Firebase Auth UID.</p><h2 id="the-completeddates-array-structure" tabindex="-1">The <code>completedDates</code> Array Structure <a class="header-anchor" href="#the-completeddates-array-structure" aria-label="Permalink to &quot;The `completedDates` Array Structure&quot;">​</a></h2><p>Instead of creating a new document in a subcollection every time a user completes a habit, the system pushes an ISO date string (<code>&quot;YYYY-MM-DD&quot;</code>) into the <code>completedDates</code> array field on the habit itself.</p><h3 id="why-this-approach" tabindex="-1">Why this approach? <a class="header-anchor" href="#why-this-approach" aria-label="Permalink to &quot;Why this approach?&quot;">​</a></h3><ol><li><strong>Massively Reduced Reads:</strong> When rendering the dashboard, the app only executes 1 read per habit. If completions were stored as separate documents, rendering 5 habits over a month would cost 150 reads instead of 5.</li><li><strong>Simplified Calculation:</strong> The streak and heatmap algorithms operate entirely client-side. They simply take the <code>completedDates</code> array, sort it, and compute the math instantly without needing complex server-side aggregations.</li></ol><h3 id="the-timezone-solution" tabindex="-1">The Timezone Solution <a class="header-anchor" href="#the-timezone-solution" aria-label="Permalink to &quot;The Timezone Solution&quot;">​</a></h3><p>When a user clicks &quot;Complete&quot;, the system does not use a raw <code>new Date()</code> object, which contains localized hour/minute data.</p><p>Instead, it passes the date through a <code>getTodayStr()</code> utility function that standardizes the current date to a strictly local ISO string (e.g. <code>&quot;2026-08-12&quot;</code>). This prevents notorious timezone bugs where a user completes a habit at 11:50 PM, but the database saves it as &quot;tomorrow&quot; because the server is in UTC.</p>',11))])}const T=r(m,[["render",p]]);export{D as __pageData,T as default};
